css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: calc(var(--loader-size) * .78); height: var(--loader-size); position: relative; }
.loader .tube { position: absolute; left: 38%; top: 0; width: 24%; height: 44%; border-radius: 3px; overflow: hidden; box-shadow: inset 0 0 0 2px color-mix(in srgb, var(--accent) 40%, transparent); }
.loader .level { position: absolute; left: 0; right: 0; top: 0; height: 92%; background: linear-gradient(color-mix(in srgb, #fff 25%, var(--accent)), var(--accent)); animation: titr-drain calc(var(--loader-speed) * 3.4) linear infinite; }
.loader .tap { position: absolute; left: 34%; top: 44%; width: 32%; height: 7%; border-radius: 2px; background: #64748b; }
.loader i { position: absolute; left: 46%; top: 52%; width: 8%; height: 9%; border-radius: 50% 50% 50% 50% / 66% 66% 34% 34%; background: var(--accent); opacity: 0; animation: titr-drip calc(var(--loader-speed) * .85) ease-in infinite; }
.loader .flask { position: absolute; left: 20%; right: 20%; bottom: 2%; height: 34%; overflow: hidden; background: color-mix(in srgb, var(--accent-2) 20%, transparent); clip-path: polygon(36% 0, 64% 0, 100% 100%, 0 100%); }
.loader .liquid { position: absolute; left: 0; right: 0; bottom: 0; height: 46%; background: var(--accent-2); animation: titr-turn calc(var(--loader-speed) * 3.4) ease-in-out infinite; }
@keyframes titr-drain { 0%, 4% { height: 92%; } 80% { height: 6%; } 94%, 100% { height: 92%; } }
@keyframes titr-drip { 0% { opacity: 0; transform: translateY(0) scale(.5); } 15% { opacity: 1; transform: translateY(0) scale(1); } 100% { opacity: 0; transform: translateY(340%) scale(.7); } }
@keyframes titr-turn { 0%, 60% { background: var(--accent-2); } 82%, 100% { background: var(--accent); } }
